mapper.select:
SELECT n.id, n.title, n.notice_type, n.publish_time, (r.id IS NOT NULL) AS read_flag FROM sys_notice n LEFT JOIN sys_notice_read r ON WHERE n.deleted = 0 AND n.status = 0 AND n.publish_time <= #{now} AND
AND n.notice_type = #{noticeType}
ORDER BY n.publish_time DESC, n.id DESC

SELECT n.id AS notice_id, #{userId} AS user_id, n.version AS read_version

  AND n.id > #{afterNoticeId}
ORDER BY n.id
LIMIT #{batchSize}

mapper.update:
UPDATE sys_notice n
INNER JOIN sys_notice cutoff ON cutoff.id = #{throughId} AND cutoff.recipient_user_id = n.recipient_user_id
SET n.deleted = n.id, n.delete_by = #{userId}, n.delete_time = #{now}
WHERE n.recipient_user_id = #{userId} AND n.notice_type = 3 AND n.status = 0 AND n.deleted = 0
  AND cutoff.notice_type = 3 AND cutoff.status = 0 AND cutoff.deleted = 0 AND cutoff.publish_time <= #{now}
  AND (n.publish_time < cutoff.publish_time OR (n.publish_time = cutoff.publish_time AND n.id <= cutoff.id))
